xml.Script:
        R := 0.4;
        include 'Figures\Scripts\Dodecahedron_Coordinates.inc';
        include 'Figures\Scripts\Dodecahedron_Standard_Colors.inc';
        D := (Rsin + R2sin) / 2 * 1.069;
        D1 := D;
        D2 := D1 + (Rsin - D) / 3;
        D3 := D2 + (Rsin - D) / 3;

        // planes of symmetry (Unit vectors, Distance = D)
        Px[0] := Cx[2] / RSin;
        Py[0] := Cy[2] / RSin;
        Pz[0] := Cz[2] / RSin;
        Px[1] := Cx[4] / RSin;
        Py[1] := Cy[4] / RSin;
        Pz[1] := Cz[4] / RSin;

        // centers of cores
        Tx[0] := Px[0] * 2 * D;
        Ty[0] := Py[0] * 2 * D;
        Tz[0] := Pz[0] * 2 * D;
        Tx[1] := Px[1] * 2 * D;
        Ty[1] := Py[1] * 2 * D;
        Tz[1] := Pz[1] * 2 * D;

        procedure ReflectVector(CNo, pNo, i); // Center [CNo] reflects via plane [pNo], and writes to variable [i]
        begin
            L := 2 * (Cx[CNo] * Px[pNo] + Cy[CNo] * Py[pNo] + Cz[CNo] * Pz[pNo]);
            VRx[i] := Cx[CNo] - Px[pNo] * L;
            VRy[i] := Cy[CNo] - Py[pNo] * L;
            VRz[i] := Cz[CNo] - Pz[pNo] * L;
        end;

        // axes
        ReflectVector( 8, 0, 0);
        ReflectVector(11, 0, 1);
        ReflectVector( 5, 0, 2);
        ReflectVector( 6, 0, 3);
        ReflectVector( 8, 1, 4);
        ReflectVector(11, 1, 5);
        ReflectVector(10, 1, 6);
        ReflectVector( 1, 1, 7);

        procedure Exchange2Colors(c1, c2);
        begin
            C := Colors[c1];
            Colors[c1] := Colors[c2];
            Colors[c2] := C;
        end;

        procedure ReflectColors();
        begin
            Exchange2Colors( 0, 3);
            Exchange2Colors( 5, 6);
            Exchange2Colors( 8,11);
            Exchange2Colors( 1,10);
        end;

